@startuml

class User {
  + UserID : int
  + Name : string
  + Email : string
  + Birthdate : date
}

class Account {
  + AccountNumber : int
  + Type : string
  + MonthlyFee : double
}

class BusinessAccount {}

class PersonalAccount {}

class Page {
  + PageName : string
  + Visits : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "*" Account
Account "0..*" -- "1" Page
PersonalAccount --|> Account
BusinessAccount --|> Account
AdvertisementPage --|> Page

@enduml

